package net.civeira.phylax.feature.access.resourceserver.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServer;
import net.civeira.phylax.feature.access.resourceserver.domain.event.ResourceServerEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ResourceServerEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ResourceServerEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ResourceServer entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
